inline const int g_api_count =
    static_cast<int>(sizeof(g_api_table) / sizeof(g_api_table[0]));
inline const int kApiMissingMax = 256;
inline const char* g_api_missing[kApiMissingMax];
inline int g_api_missing_count = 0;

// Resolve every binding from its owning module.  A null module argument means
// "not provided": bindings for it stay null and do NOT fail resolution (the
// runner aborts a scenario that touches them).  A non-null module must resolve
// ALL of its bindings; any GetProcAddress miss is recorded in g_api_missing
// and makes the return value false.
inline bool resolve_api(HMODULE core, HMODULE ext, HMODULE device) {
  g_api_missing_count = 0;
  for (int i = 0; i < g_api_count; ++i) *g_api_table[i].target = nullptr;
  bool ok = true;
  for (int i = 0; i < g_api_count; ++i) {
    const ApiModuleInfo& e = g_api_table[i];
    const HMODULE m = (e.module == kApiModuleCore)
                          ? core
                          : (e.module == kApiModuleExt) ? ext : device;
    if (m == nullptr) continue;
    void* p = reinterpret_cast<void*>(GetProcAddress(m, e.symbol));
    if (p == nullptr) {
      if (g_api_missing_count < kApiMissingMax)
        g_api_missing[g_api_missing_count++] = e.name;
      ok = false;
      continue;
    }
    *e.target = p;
  }
  return ok;
}

// ----------------------------------------------------------------------------
// Runner support: error-callback capture, scenario seed, abort signal.
// ----------------------------------------------------------------------------
namespace apitest {

// Incremented by flexErrorCallback; the runner resets it per scenario so
// records are named error.0, error.1, ... from a clean slate.
inline int g_flex_error_seq = 0;

// Installed by the runner before dispatching a scenario.  The sink emits an
// `error.<n>` record (strict=false) with the message text and notes the
// file/line from FleX's error report.
inline void (*g_flex_error_sink)(const char* name, const char* msg,
                                 const char* file, int line) = nullptr;

// NvFlexErrorCallback-compatible; scenario packs pass this to
// api::NvFlexInit(NV_FLEX_VERSION, apitest::flexErrorCallback, nullptr) so
// FleX's own error reports are captured as records instead of lost.
inline void flexErrorCallback(NvFlexErrorSeverity /*type*/, const char* msg,
                              const char* file, int line) {
  char name[32];
  std::snprintf(name, sizeof(name), "error.%d", g_flex_error_seq++);
  if (g_flex_error_sink != nullptr)
    g_flex_error_sink(name, msg ? msg : "", file ? file : "", line);
}

// Fixed seed for scenario RNGs (--seed, 0 means "pack default").
inline unsigned int g_seed = 0;

// Thrown by scenarios (or helpers) to abort the current scenario cleanly: the
// runner catches it, notes the abort, flushes records and exits with code 5.
struct ScenarioAbort {};

} // namespace apitest

